package com.huskydg.magicv2ray;

import android.content.BroadcastReceiver;
import android.content.Context;
import android.content.Intent;
import android.os.Bundle;
import android.os.IBinder;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.concurrent.CompletableFuture;

/**
 * Receives the Binder of the app_process helper (HotspotMain). The receiver has to be exported
 * because the sender is the shell user, so the one-time nonce (generated by the app, handed to the
 * helper on its command line, which other apps cannot read) is what authenticates the sender.
 */
public final class HotspotBinderReceiver extends BroadcastReceiver {

    private static final Object LOCK = new Object();
    private static String expectedNonce;
    private static CompletableFuture<IBinder> pending;

    /** Call before launching the helper. Replaces any earlier, unfinished expectation. */
    static CompletableFuture<IBinder> expect(String nonce) {
        synchronized (LOCK) {
            if (pending != null) pending.cancel(false);
            expectedNonce = nonce;
            pending = new CompletableFuture<>();
            return pending;
        }
    }

    static void cancel() {
        synchronized (LOCK) {
            if (pending != null) pending.cancel(false);
            pending = null;
            expectedNonce = null;
        }
    }

    @Override
    public void onReceive(Context context, Intent intent) {
        if (intent == null || !HotspotMain.ACTION.equals(intent.getAction())) return;
        String nonce = intent.getStringExtra(HotspotMain.EXTRA_NONCE);
        Bundle bundle = intent.getBundleExtra(HotspotMain.EXTRA_BUNDLE);
        if (nonce == null || bundle == null) return;
        IBinder binder = bundle.getBinder(HotspotMain.KEY_BINDER);
        if (binder == null) return;
        synchronized (LOCK) {
            if (pending == null || expectedNonce == null) return;
            if (!MessageDigest.isEqual(expectedNonce.getBytes(StandardCharsets.UTF_8),
                    nonce.getBytes(StandardCharsets.UTF_8))) return;
            pending.complete(binder);
            expectedNonce = null;           // one binder per launch
        }
    }
}
